        col_vals = [grid[r][c] for r in range(rows)]
        if len(set(col_vals)) == 1:
            vert_seps.append((c, col_vals[0]))
        elif len(set(col_vals)) <= 2:  # Allow one different value (like the intersection)
            most_common = max(set(col_vals), key=col_vals.count)
            if col_vals.count(most_common) >= rows - 2:
                vert_seps.append((c, most_common))

