        elif len(set(row_vals)) <= 3:
            most_common = max(set(row_vals), key=row_vals.count)
            if row_vals.count(most_common) >= cols - 3:
                horiz_seps.append((r, most_common))

    # Sort by position
    vert_seps.sort(key=lambda x: x[0])
    horiz_seps.sort(key=lambda x: x[1])

    # Get the bounding separators (innermost two)
    if len(vert_seps) >= 2:
        left_sep = vert_seps[0]
        right_sep = vert_seps[-1]
