            # Fall right: stack at right
            for r in range(1, reg_rows - 1):
                count = sum(1 for c in range(reg_cols) if region[r][c] == obj_val)
                for i in range(count):
                    if reg_cols - 2 - i >= 1:
                        output[r][reg_cols - 2 - i] = obj_val
